# -*- coding: utf-8 -*-
# N1 内容理解(中文) tambahan 2 · 3問 / 各
P1 = "Pahami argumen utama penulis: biasanya di kalimat penutup atau setelah しかし/とはいえ/むしろ."
P2 = "Soal alasan/指示語: baca kalimat sebelum dan sesudah bagian bergaris bawah; jawaban hampir selalu di sana."
P3 = "Pilihan yang memutlakkan (すべて・必ず・全く) atau memuat hal di luar teks hampir pasti salah."
JN = 'Teks menengah (内容理解・中文)'
R = ['Tidak disebut dalam teks.', 'Berlawanan dengan isi teks.', 'Berlebihan / bukan argumen penulis.']
def C(jp, id, qs):
    return dict(slot='chu', jenis=JN, jp=jp, id=id, qs=[(q, [ok] + w, 0, al, bu, R, [P2, P3, P1][i % 3]) for i, (q, ok, w, al, bu) in enumerate(qs)])
B = [
 C('人は、自分の行動の理由を、後から作り上げる傾向があるという。心理学の実験では、被験者に無意識のうちに選ばせた物について、理由を尋ねると、もっともらしい理由が、淀みなく語られた。\n　これは、私たちが自分の意思で選んでいるという感覚が、必ずしも事実を反映していないことを示している。選択の理由は、選んだ後に、整合性を保つために作られている可能性がある。\n　もちろん、すべての判断が後付けというわけではない。しかし、自分の判断を過信せず、「なぜそう思うのか」を、時には疑ってみる姿勢が、思い込みから身を守る助けになるだろう。',
   'Dikatakan manusia cenderung menyusun alasan tindakannya belakangan. Dalam eksperimen psikologi, ketika partisipan ditanya alasan atas barang yang dipilih tanpa sadar, mereka menjelaskan alasan yang masuk akal dengan lancar.\n Ini menunjukkan perasaan bahwa kita memilih dengan kehendak sendiri belum tentu mencerminkan kenyataan. Mungkin alasan pilihan dibuat setelah memilih demi menjaga konsistensi.\n Tentu tak semua penilaian bersifat belakangan. Namun sikap tak terlalu percaya pada penilaian sendiri dan sesekali meragukan "mengapa aku berpikir begitu" akan membantu melindungi diri dari prasangka.',
   [('実験で、被験者はどうしたか。','無意識に選んだ物について、もっともらしい理由を淀みなく語った',['理由を全く答えられなかった','理由を尋ねられて怒った','選んだ物をすぐに変えた'],'Eksperimen.','もっともらしい理由が、淀みなく語られた'),
    ('実験の結果が示していることは何か。','自分の意思で選んでいるという感覚が、事実を反映しているとは限らないこと',['人は常に論理的に選ぶこと','選択に理由は必要ないこと','無意識の選択は必ず正しいこと'],'Makna.','必ずしも事実を反映していない'),
    ('筆者が、思い込みから身を守るために勧めていることは何か。','自分の判断を過信せず、時には「なぜそう思うのか」を疑ってみること',['判断を他人に任せること','理由を考えないこと','すべての判断を疑うこと'],'Saran.','「なぜそう思うのか」を、時には疑ってみる姿勢')]),
 C('近年、「ミニマリズム」が注目されているが、その根底にあるのは、物を減らすこと自体ではなく、自分にとって本当に必要なものを見極めることだと言われる。\n　物があふれる社会では、買うことが満足につながると錯覚しがちである。しかし、物が増えるほど、管理の手間や、選択の疲れも増えていく。\n　一方で、ミニマリズムが、新たな「正しさ」の押し付けになる危険もある。物を持たないこと自体が目的になれば、それはかつての物欲と同じく、物に振り回されている状態にほかならない。大切なのは、数ではなく、自分の価値観に基づいて選ぶことであろう。',
   'Belakangan "minimalisme" menarik perhatian, tetapi dikatakan landasannya bukan mengurangi barang itu sendiri, melainkan menilai apa yang benar-benar diperlukan.\n Di masyarakat yang barangnya melimpah, orang cenderung mengira membeli berujung kepuasan. Namun makin banyak barang, makin bertambah pula repot mengelola dan lelah memilih.\n Di sisi lain ada bahaya minimalisme menjadi pemaksaan "kebenaran" baru. Bila tak punya barang menjadi tujuan, itu sama dengan keinginan memiliki dulu, yaitu keadaan diombang-ambingkan barang. Yang penting memilih berdasarkan nilai diri, bukan jumlah.',
   [('ミニマリズムの根底にあるものは何か。','自分にとって本当に必要なものを見極めること',['物を減らすこと自体','物を買うこと','物を捨てること'],'Landasan.','本当に必要なものを見極めること'),
    ('物が増えるとどんな問題が生じるか。','管理の手間や選択の疲れが増える',['お金が増える','満足が必ず高まる','部屋が広くなる'],'Masalah.','管理の手間や、選択の疲れも増えていく'),
    ('筆者の考えに合うものはどれか。','物を持たないこと自体を目的にするのも、物に振り回されている状態だ',['ミニマリズムは常に正しい','物は多いほどよい','物を持たないことが最終目標だ'],'Pendapat.','物に振り回されている状態にほかならない')]),
 C('日本の地方都市では、中心市街地の商店街が衰退し、郊外の大型店舗に客が流れている。車で来られる大型店は、品ぞろえが豊富で、価格も安い。商店街の個人商店は、価格では太刀打ちできない。\n　しかし、商店街には、大型店にはない価値がある。店主と客の会話、季節ごとの行事、顔の見える関係は、地域の人々のつながりを支えてきた。\n　最近、空き店舗を活用して、高齢者向けの交流の場や、子育て世代が集うカフェを開く試みが広がっている。商店街の役割は、単に物を売ることから、地域の居場所を提供することへと変わりつつあるのだろう。',
   'Di kota daerah Jepang, pusat pertokoan di tengah kota merosot dan pelanggan mengalir ke toko besar di pinggiran. Toko besar yang bisa dicapai mobil punya barang lengkap dan harga murah. Toko perorangan di pertokoan tak bisa menandingi dari segi harga.\n Namun pertokoan punya nilai yang tak dimiliki toko besar. Percakapan pemilik dan pelanggan, acara musiman, dan hubungan saling kenal menopang ikatan warga.\n Belakangan upaya memanfaatkan toko kosong untuk tempat interaksi lansia dan kafe tempat berkumpul generasi pengasuh anak meluas. Peran pertokoan tampaknya berubah dari sekadar menjual barang menjadi menyediakan tempat berada bagi daerah.',
   [('大型店に客が流れるのはなぜか。','品ぞろえが豊富で、価格も安いから',['商店街が駅から遠いから','店主が親切でないから','営業時間が長いから'],'Sebab.','品ぞろえが豊富で、価格も安い'),
    ('商店街が持っている価値として、文章に合うものはどれか。','店主と客の会話や行事など、顔の見える関係',['価格の安さ','品ぞろえの豊富さ','駐車場の広さ'],'Nilai.','顔の見える関係は、地域の人々のつながりを支えてきた'),
    ('筆者は、商店街の役割がどう変わりつつあると述べているか。','物を売る場から、地域の居場所を提供する場へ',['居場所を提供する場から物を売る場へ','大型店と競う場へ','役割を終える場へ'],'Perubahan peran.','地域の居場所を提供することへと変わりつつある')]),
 C('科学者は、客観的な事実だけを扱うと思われがちである。しかし、実際の研究では、何を問うか、どの現象に注目するかという最初の選択に、研究者の関心や価値観が深く関わっている。\n　また、同じデータからでも、解釈は研究者によって異なりうる。科学の客観性は、個人が完全に中立であることではなく、他の研究者による検証と批判にさらされることによって保たれている。\n　つまり、科学を信頼できるものにしているのは、個々の研究者の誠実さに加えて、間違いを互いに指摘し合う仕組みなのである。この仕組みを理解することは、科学の成果を正しく評価するために欠かせない。',
   'Ilmuwan cenderung dianggap hanya menangani fakta objektif. Namun dalam penelitian nyata, pada pilihan awal tentang apa yang ditanyakan dan fenomena mana yang diperhatikan, minat dan nilai peneliti sangat terkait.\n Selain itu, dari data yang sama pun tafsir bisa berbeda tiap peneliti. Objektivitas sains terjaga bukan karena individu sepenuhnya netral, melainkan karena terpapar pada verifikasi dan kritik peneliti lain.\n Artinya, yang membuat sains dapat dipercaya adalah, selain ketulusan peneliti, mekanisme saling menunjukkan kesalahan. Memahami mekanisme ini tak terhindarkan untuk menilai hasil sains dengan benar.',
   [('研究者の関心や価値観が関わるのはどこか。','何を問うか、どの現象に注目するかという最初の選択',['データの数値そのもの','結果の検証','論文の印刷'],'Peran nilai.','最初の選択に、研究者の関心や価値観が深く関わっている'),
    ('科学の客観性は何によって保たれているか。','他の研究者による検証と批判',['個人が完全に中立であること','研究費の多さ','研究者の数'],'Objektivitas.','検証と批判にさらされることによって'),
    ('筆者が、欠かせないと述べていることは何か。','間違いを指摘し合う仕組みを理解すること',['科学者を信じること','研究を批判しないこと','データを集めないこと'],'Yang penting.','この仕組みを理解することは…欠かせない')]),
 C('「リーダーシップ」というと、強い意志で人を引っ張る姿を思い浮かべる人が多い。しかし、近年は、メンバーの話を聞き、能力を引き出す「支援型」のリーダーシップが評価されている。\n　変化の速い現代では、一人のリーダーがすべてを把握し、正しい判断を下すことは難しい。現場に近いメンバーのほうが、状況をよく理解していることも多い。\n　そのため、リーダーには、自分の答えを示すことより、メンバーが考え、発言しやすい環境を整えることが求められる。強さとは、決して弱さを見せないことではなく、自分の限界を認め、他者の力を借りられることなのかもしれない。',
   'Bila bicara "kepemimpinan", banyak orang membayangkan sosok yang menarik orang dengan kehendak kuat. Namun belakangan kepemimpinan "tipe pendukung" yang mendengar anggota dan menggali kemampuan mereka dihargai.\n Di zaman yang cepat berubah, sulit bagi satu pemimpin memahami semuanya dan membuat penilaian benar. Anggota yang dekat dengan lapangan sering lebih memahami situasi.\n Karena itu, pemimpin dituntut bukan menunjukkan jawabannya sendiri, melainkan menyiapkan lingkungan agar anggota mudah berpikir dan bicara. Kekuatan mungkin bukan tak pernah menunjukkan kelemahan, melainkan mengakui keterbatasan diri dan bisa meminjam tenaga orang lain.',
   [('近年評価されているリーダーシップはどれか。','メンバーの話を聞き、能力を引き出す支援型',['強い意志で人を引っ張る型','何も指示しない型','一人で決める型'],'Tipe.','メンバーの話を聞き、能力を引き出す「支援型」'),
    ('一人のリーダーがすべてを判断するのが難しい理由は何か。','変化が速く、現場のメンバーのほうが状況をよく理解していることも多いから',['メンバーが働かないから','リーダーの数が少ないから','判断する必要がないから'],'Alasan.','変化の速い現代…現場に近いメンバーのほうが'),
    ('筆者の考える強さとは何か。','自分の限界を認め、他者の力を借りられること',['弱さを決して見せないこと','自分の答えを常に示すこと','他者に頼らないこと'],'Definisi.','自分の限界を認め、他者の力を借りられること')]),
 C('日本では、ごみの分別が細かく、資源として再利用される割合も高い。しかし、リサイクルの割合が高いことが、そのまま環境への負荷の低さを意味するわけではない。\n　リサイクルには、回収や運搬、再加工のために、エネルギーが必要である。また、リサイクルがあるという安心感から、物を使い捨てる量が増えるという指摘もある。\n　環境への負荷を減らす最も効果的な方法は、そもそも、ごみを出さないことである。使い捨ての物を買わない、長く使える物を選ぶ。そうした消費のあり方を見直さなければ、リサイクルだけでは、問題の根本は解決しない。',
   'Di Jepang pemilahan sampah rinci dan proporsi yang didaur ulang sebagai sumber daya pun tinggi. Namun tingginya persentase daur ulang tak langsung berarti rendahnya beban lingkungan.\n Daur ulang butuh energi untuk pengumpulan, pengangkutan, dan pengolahan ulang. Ada pula pendapat bahwa rasa aman karena ada daur ulang meningkatkan jumlah barang sekali pakai yang dibuang.\n Cara paling efektif mengurangi beban lingkungan adalah pada dasarnya tidak menghasilkan sampah. Tidak membeli barang sekali pakai, memilih barang yang awet. Bila cara konsumsi tak ditinjau, daur ulang saja tak menyelesaikan akar masalah.',
   [('リサイクルの問題点として、文章が述べているものはどれか。','回収や再加工にエネルギーが必要で、使い捨てが増える可能性もある',['費用が全くかからない','環境に必ず良い','ごみが増えない'],'Masalah.','エネルギーが必要…使い捨てる量が増える'),
    ('最も効果的な方法として筆者が挙げているものは何か。','ごみを出さないこと',['分別を細かくすること','リサイクルを増やすこと','ごみを燃やすこと'],'Cara efektif.','ごみを出さないこと'),
    ('筆者の主張に合うものはどれか。','消費のあり方を見直さなければ根本的な解決にならない',['リサイクルだけで十分だ','物は使い捨てるべきだ','消費は増やすべきだ'],'Pendapat.','消費のあり方を見直さなければ')]),
 C('「幸福」を測る試みは、世界各地で行われている。国の豊かさを示す指標として、長く用いられてきたのは国内総生産だが、それだけでは、人々の暮らしの質を捉えきれないという批判がある。\n　そこで、健康、教育、人間関係、環境など、多様な側面から幸福度を測る指標が考案された。調査の結果、経済的に豊かな国でも、必ずしも幸福度が高いとは限らないことが分かってきた。\n　ただし、幸福は主観的なもので、文化や価値観によって、その捉え方は異なる。数値だけで国を比べるのではなく、数値の背景にある人々の実感に目を向けることが重要だ。',
   'Upaya mengukur "kebahagiaan" dilakukan di berbagai tempat dunia. Sebagai indikator kekayaan negara, yang lama dipakai adalah produk domestik bruto, tetapi ada kritik bahwa itu saja tak menangkap mutu kehidupan rakyat.\n Maka dirancang indikator yang mengukur tingkat kebahagiaan dari aspek beragam seperti kesehatan, pendidikan, hubungan antarmanusia, dan lingkungan. Hasil survei menunjukkan negara kaya pun belum tentu tinggi kebahagiaannya.\n Namun kebahagiaan bersifat subjektif dan cara memahaminya berbeda menurut budaya dan nilai. Penting bukan membandingkan negara hanya dengan angka, tetapi memperhatikan perasaan nyata orang di balik angka.',
   [('国内総生産に対する批判は何か。','人々の暮らしの質を捉えきれないという批判',['数値が計算できないという批判','国の数が多すぎるという批判','幸福に関係しすぎるという批判'],'Kritik.','暮らしの質を捉えきれない'),
    ('調査から分かってきたことは何か。','経済的に豊かな国でも、必ずしも幸福度が高いとは限らないこと',['豊かな国は必ず幸福であること','貧しい国は必ず不幸であること','幸福は測れないこと'],'Temuan.','必ずしも幸福度が高いとは限らない'),
    ('筆者が重要だと述べていることは何か。','数値の背景にある人々の実感に目を向けること',['数値だけで国を比べること','幸福を測るのをやめること','文化の違いを無視すること'],'Pesan.','数値の背景にある人々の実感に目を向ける')]),
 C('日本語の「すみません」は、謝罪にも感謝にも使われる便利な言葉である。この言葉の背後には、相手に手間をかけさせたことへの申し訳なさという、日本人特有の感覚があるという。\n　外国語に翻訳すると、状況によって「ごめんなさい」や「ありがとう」に訳し分けなければならず、微妙なニュアンスが失われる。\n　しかし、これを日本語の曖昧さとして批判するのは短絡的であろう。相手の負担を思いやる気持ちを、感謝と同時に伝えられる言葉があるという事実は、むしろ日本語の豊かさの一端を示しているとも言えるのではないか。',
   'Kata "sumimasen" dalam bahasa Jepang adalah kata praktis yang dipakai untuk meminta maaf dan berterima kasih. Di balik kata ini, katanya ada perasaan khas orang Jepang: merasa tak enak karena merepotkan lawan.\n Bila diterjemahkan ke bahasa asing, harus dibedakan menurut situasi menjadi "maaf" atau "terima kasih" dan nuansa halus hilang.\n Namun mengkritik ini sebagai ketaksaan bahasa Jepang terlalu dangkal. Fakta bahwa ada kata yang bisa menyampaikan perasaan memikirkan beban lawan sekaligus rasa terima kasih bisa dikatakan menunjukkan sebagian kekayaan bahasa Jepang.',
   [('「すみません」の背後にある感覚は何か。','相手に手間をかけさせたことへの申し訳なさ',['相手への怒り','自分への自信','お金を払う気持ち'],'Perasaan.','手間をかけさせたことへの申し訳なさ'),
    ('翻訳するとどうなるか。','状況によって訳し分ける必要があり、微妙なニュアンスが失われる',['簡単に一つの言葉で訳せる','意味が強まる','訳せなくなる'],'Terjemahan.','訳し分けなければならず…ニュアンスが失われる'),
    ('筆者は、「すみません」をどう評価しているか。','日本語の豊かさの一端を示している',['日本語の曖昧さを示している','不要な言葉だ','外国語より劣っている'],'Penilaian.','日本語の豊かさの一端を示している')]),
 C('新聞は、事実を伝える媒体であると同時に、何を重要な出来事として取り上げるかを選ぶ媒体でもある。紙面の大きさには限りがあるため、すべての出来事を載せることはできない。\n　この「選ぶ」という行為には、編集者の判断が入り込む。どの出来事を一面に載せるか、どの見出しをつけるかによって、読者が受ける印象は大きく変わる。\n　したがって、読者には、記事の内容を鵜呑みにせず、なぜこの出来事が取り上げられ、別の出来事は取り上げられなかったのかを考える姿勢が求められる。複数の新聞を読み比べることは、その有効な方法の一つである。',
   'Koran adalah media yang menyampaikan fakta sekaligus media yang memilih kejadian mana yang dimuat sebagai penting. Karena ukuran halaman terbatas, tak semua kejadian bisa dimuat.\n Pada tindakan "memilih" ini masuk penilaian editor. Kejadian mana ditaruh di halaman depan dan judul apa dipasang sangat mengubah kesan pembaca.\n Karena itu pembaca dituntut sikap tak menelan mentah isi berita dan memikirkan mengapa kejadian ini dimuat sementara yang lain tidak. Membandingkan beberapa koran adalah salah satu cara efektif.',
   [('新聞が「選ぶ」媒体であるのはなぜか。','紙面に限りがあり、すべての出来事を載せられないから',['記者が少ないから','読者が選ぶから','事実を伝えないから'],'Sebab.','紙面の大きさには限りがある'),
    ('読者が受ける印象は何によって変わるか。','どの出来事を一面に載せ、どんな見出しをつけるか',['新聞の値段','紙の色','配達の時間'],'Pengaruh.','一面に載せるか…見出しをつけるかによって'),
    ('筆者が有効な方法として挙げているのは何か。','複数の新聞を読み比べること',['新聞を読まないこと','一つの新聞だけを信じること','見出しだけを読むこと'],'Cara.','複数の新聞を読み比べる')]),
 C('「待つ」ことは、現代人にとって、ますます難しくなっている。メッセージにはすぐ返事が来ることを期待し、商品は翌日に届くのが当たり前になった。\n　便利さは、私たちから「待つ時間」を奪ってきた。しかし、待つ時間は、単なる無駄ではない。相手のことを思いやったり、結果を楽しみにしたり、自分の気持ちを整理したりする、大切な時間でもあったはずだ。\n　すぐに答えを求める習慣は、物事をじっくり考える力も弱めてしまう。ときには、意識して待つことを楽しみ、結論を急がない余裕を持ちたいものである。',
   '"Menunggu" makin sulit bagi manusia modern. Kita mengharapkan balasan pesan segera dan barang tiba esok hari sudah lumrah.\n Kepraktisan telah merampas "waktu menunggu" dari kita. Namun waktu menunggu bukan sekadar sia-sia. Seharusnya juga waktu penting untuk memikirkan lawan, menantikan hasil, dan merapikan perasaan sendiri.\n Kebiasaan segera menuntut jawaban juga melemahkan kemampuan memikirkan sesuatu dengan saksama. Sesekali ingin dengan sadar menikmati menunggu dan memiliki kelonggaran tak tergesa mengambil kesimpulan.',
   [('現代人にとって「待つ」ことが難しくなったのはなぜか。','すぐに返事が来る、翌日に届くなど、便利さが当たり前になったから',['待つ時間が長くなったから','人が忙しくなくなったから','返事が遅くなったから'],'Alasan.','メッセージにはすぐ返事が来る…翌日に届くのが当たり前'),
    ('待つ時間にはどんな意味があったと筆者は述べているか。','相手を思いやり、結果を楽しみにし、気持ちを整理する大切な時間',['何もしない無駄な時間','他人を急かす時間','お金を節約する時間'],'Arti menunggu.','相手のことを思いやったり…気持ちを整理したり'),
    ('筆者が望んでいることは何か。','意識して待つことを楽しみ、結論を急がない余裕を持つこと',['すぐに答えを求めること','便利さをすべてなくすこと','待つことを避けること'],'Harapan.','結論を急がない余裕を持ちたい')]),
]
